import re
from pathlib import Path
ROOT=Path('.')
TOKEN=re.compile(r'samples/([A-Za-z0-9_.-]+):(\d+)(?:-(\d+))?')
PT=re.compile(r"\b(n[aã]o|se[cç][aã]o|configura[cç][aã]o|implementa[cç][aã]o|desempenho|seguran[cç]a|refer[eê]ncia|vis[aã]o geral|guia|usar|deve|pode|para|com|uma|dos|das|que|mais|como|est[aá]|s[aã]o|ser[aá]|apenas|talvez|conclui-se|veja)\b",re.I)
for f in ['06-static-typing-core.md','07-static-typing-workflow.md','08-data-modeling.md','09-errors-and-exception-groups.md']:
    p=Path(f); t=p.read_text(); lines=t.splitlines(); errs=[]
    print('===',f,'bytes=',len(t.encode()),'tables=',sum(1 for l in lines if re.match(r'^\|[-: |]+\|$',l)),'citations=',len(TOKEN.findall(t)))
    if not re.match(r'^# \d{2} - ',lines[0]): errs.append('heading')
    if not 5600<=len(t.encode())<=8200: errs.append('bytes')
    if not re.search(r'^## Sources\s*$',t,re.M): errs.append('sources')
    if t.strip().split('\n## Sources')[0].count('```')%2: errs.append('fence-balance')
    for i,l in enumerate(lines,1):
        if PT.search(re.sub(r'`[^`]*`','',l)) and not l.lstrip().startswith('- http'): errs.append(f'PT{i}')
        if any(x in l for x in ('TODO','PLACEHOLDER','FIXME')): errs.append(f'marker{i}')
    for m in TOKEN.finditer(t):
        s=ROOT/'samples'/m.group(1)
        if not s.is_file(): errs.append('missing '+m.group(0)); continue
        n=len(s.read_text(errors='replace').splitlines())
        lo,hi=int(m.group(2)),int(m.group(3) or m.group(2))
        if not (1<=lo<=hi<=n): errs.append('range '+m.group(0)+f' (n={n})')
    blocks=re.findall(r'^```(\w*)\n(.*?)^```',t,re.M|re.S)
    for lang,b in blocks:
        if not lang: errs.append('no fence language')
        if len(b.splitlines())>25: errs.append('fence >25 lines')
    tail=t.rsplit('\n## Sources',1)[-1]
    urls=re.findall(r'https?://\S+',tail)
    if len(urls)<5: errs.append('urls<5')
    print('  urls=',len(urls),'fences=',len(blocks),'ERRORS=',errs)
PY
